1. // This Source Code Form is subject to the terms of the Mozilla Public
2. // License, v. 2.0. If a copy of the MPL was not distributed with this
3. // file, You can obtain one at https://mozilla.org/MPL/2.0/.
4. 
5. use std::path::Path;
6. 
7. use log::{debug, trace};
8. use petgraph::{graph::NodeIndex, stable_graph::StableGraph};
9. use ra_ap_hir::{self, Crate};
10. use ra_ap_ide::{AnalysisHost, RootDatabase};
11. use ra_ap_paths::AbsPathBuf;
12. use ra_ap_proc_macro_api::ProcMacroServer;
13. use ra_ap_project_model::{
14.     CargoConfig, PackageData, ProjectManifest, ProjectWorkspace, TargetData, UnsetTestCrates,
15. };
16. use ra_ap_rust_analyzer::cli::load_cargo::{load_workspace, LoadCargoConfig};
17. use ra_ap_vfs::Vfs;
18. use structopt::StructOpt;
19. 
20. use crate::{
21.     graph::{
22.         builder::{Builder as GraphBuilder, Options as GraphBuilderOptions},
23.         edge::Edge,
24.         node::Node,
25.         util,
26.     },
27.     options::{
28.         general::Options as GeneralOptions, graph::Options as GraphOptions,
29.         project::Options as ProjectOptions,
30.     },
31.     target::{select_package, select_target},
32. };
33. 
34. pub mod graph;
35. pub mod tree;
36. 
37. #[derive(StructOpt, Clone, PartialEq, Eq, Debug)]
38. pub enum Command {
39.     #[structopt(name = "tree", about = "Print crate as a tree.")]
40.     Tree(tree::Options),
41. 
42.     #[structopt(
43.         name = "graph",
44.         about = "Print crate as a graph.",
45.         after_help = r#"
46.         If you have xdot installed on your system, you can run this using:
47.         `cargo modules generate dependencies | xdot -`
48.         "#
49.     )]
50.     Graph(graph::Options),
51. }
52. 
53. impl Command {
54.     pub(crate) fn sanitize(&mut self) {
55.         if self.graph_options().with_tests && !self.project_options().cfg_test {
56.             debug!("Enabling `--cfg-test`, which is implied by `--with-tests`");
57.             self.project_options_mut().cfg_test = true;
58.         }
59.     }
60. 
61.     pub fn run(&self) -> Result<(), anyhow::Error> {
62.         let general_options = self.general_options();
63.         let project_options = self.project_options();
64.         let graph_options = self.graph_options();
65. 
66.         let project_path = project_options.manifest_path.as_path().canonicalize()?;
67.         let cargo_config = self.cargo_config(project_options);
68.         let load_config = self.load_config();
69. 
70.         let progress = |string| {
71.             trace!("Progress: {}", string);
72.         };
73. 
74.         let project_workspace =
75.             self.load_project_workspace(&project_path, &cargo_config, &progress)?;
76. 
77.         let (package, target) = self.select_target(&project_workspace, project_options)?;
78. 
79.         if general_options.verbose {
80.             eprintln!();
81.             eprintln!("crate");
82.             eprintln!("└── package: {}", package.name);
83.             eprintln!("    └── target: {}", target.name);
84.             eprintln!();
85.         }
86. 
87.         let (host, vfs, _proc_macro_client) = self.analyze_project_workspace(
88.             project_workspace,
89.             &cargo_config,
90.             &load_config,
91.             &progress,
92.         )?;
93.         let db = host.raw_database();
94. 
95.         let krate = self.find_crate(db, &vfs, &target)?;
96. 
97.         let (graph, start_node_idx) = self.build_graph(db, &vfs, krate, graph_options)?;
98. 
99.         trace!("Generating ...");
100. 
101.         match self {
102.             #[allow(unused_variables)]
103.             Self::Tree(options) => {
104.                 let command = tree::Command::new(options.clone());
105.                 command.run(&graph, start_node_idx, krate, db)
106.             }
107.             #[allow(unused_variables)]
108.             Self::Graph(options) => {
109.                 let command = graph::Command::new(options.clone());
110.                 command.run(&graph, start_node_idx, krate, db)
111.             }
112.         }
113.     }
114. 
115.     fn cargo_config(&self, project_options: &ProjectOptions) -> CargoConfig {
116.         // Do not activate the `default` feature.
117.         let no_default_features = project_options.no_default_features;
118. 
119.         // Activate all available features
120.         let all_features = project_options.all_features;
121. 
122.         // List of features to activate.
123.         // (This will be ignored if `cargo_all_features` is true.)
124.         let features = project_options.features.clone();
125. 
126.         // Target triple
127.         let target = project_options.target.clone();
128. 
129.         // Don't load sysroot crates (`std`, `core` & friends).
130.         let no_sysroot = !(project_options.with_sysroot && self.with_sysroot());
131. 
132.         // rustc private crate source
133.         let rustc_source = None;
134. 
135.         // crates to disable `#[cfg(test)]` on
136.         let unset_test_crates = match project_options.cfg_test {
137.             true => UnsetTestCrates::None,
138.             false => UnsetTestCrates::All,
139.         };
140. 
141.         // Setup RUSTC_WRAPPER to point to `rust-analyzer` binary itself.
142.         // (We use that to compile only proc macros and build scripts
143.         // during the initial `cargo check`.)
144.         let wrap_rustc_in_build_scripts = true;
145. 
146.         let run_build_script_command = None;
147. 
148.         CargoConfig {
149.             no_default_features,
150.             all_features,
151.             features,
152.             target,
153.             no_sysroot,
154.             rustc_source,
155.             unset_test_crates,
156.             wrap_rustc_in_build_scripts,
157.             run_build_script_command,
158.         }
159.     }
160. 
161.     fn load_config(&self) -> LoadCargoConfig {
162.         LoadCargoConfig {
163.             load_out_dirs_from_check: true,
164.             with_proc_macro: false,
165.             prefill_caches: false,
166.         }
167.     }
168. 
169.     fn load_project_workspace(
170.         &self,
171.         project_path: &Path,
172.         cargo_config: &CargoConfig,
173.         progress: &dyn Fn(String),
174.     ) -> anyhow::Result<ProjectWorkspace> {
175.         let root = AbsPathBuf::assert(std::env::current_dir()?.join(project_path));
176.         let root = ProjectManifest::discover_single(&root)?;
177. 
178.         ProjectWorkspace::load(root, cargo_config, &progress)
179.     }
180. 
181.     fn select_target(
182.         &self,
183.         project_workspace: &ProjectWorkspace,
184.         options: &ProjectOptions,
185.     ) -> anyhow::Result<(PackageData, TargetData)> {
186.         let cargo_workspace = match project_workspace {
187.             ProjectWorkspace::Cargo { cargo, .. } => Ok(cargo),
188.             ProjectWorkspace::Json { .. } => Err(anyhow::anyhow!("Unexpected JSON workspace")),
189.             ProjectWorkspace::DetachedFiles { .. } => {
190.                 Err(anyhow::anyhow!("Unexpected detached files"))
191.             }
192.         }?;
193. 
194.         let package_idx = select_package(cargo_workspace, options)?;
195.         let package = cargo_workspace[package_idx].clone();
196.         debug!("Selected package: {:#?}", package.name);
197. 
198.         let target_idx = select_target(cargo_workspace, package_idx, options)?;
199.         let target = cargo_workspace[target_idx].clone();
200.         debug!("Selected target: {:#?}", target.name);
201. 
202.         Ok((package, target))
203.     }
204. 
205.     fn analyze_project_workspace(
206.         &self,
207.         mut workspace: ProjectWorkspace,
208.         cargo_config: &CargoConfig,
209.         load_config: &LoadCargoConfig,
210.         progress: &dyn Fn(String),
211.     ) -> anyhow::Result<(AnalysisHost, Vfs, Option<ProcMacroServer>)> {
212.         if load_config.load_out_dirs_from_check {
213.             let build_scripts = workspace.run_build_scripts(cargo_config, progress)?;
214.             workspace.set_build_scripts(build_scripts)
215.         }
216. 
217.         load_workspace(workspace, load_config)
218.     }
219. 
220.     fn find_crate(
221.         &self,
222.         db: &RootDatabase,
223.         vfs: &Vfs,
224.         target: &TargetData,
225.     ) -> anyhow::Result<Crate> {
226.         let crates = Crate::all(db);
227. 
228.         let target_root_path = target.root.as_path();
229. 
230.         let krate = crates.into_iter().find(|krate| {
231.             let vfs_path = vfs.file_path(krate.root_file(db));
232.             let crate_root_path = vfs_path.as_path().unwrap();
233. 
234.             crate_root_path == target_root_path
235.         });
236. 
237.         krate.ok_or_else(|| anyhow::anyhow!("Crate not found"))
238.     }
239. 
240.     fn build_graph(
241.         &self,
242.         db: &RootDatabase,
243.         vfs: &Vfs,
244.         krate: Crate,
245.         options: &GraphOptions,
246.     ) -> anyhow::Result<(StableGraph<Node, Edge>, NodeIndex)> {
247.         let graph_builder = {
248.             let builder_options = self.builder_options();
249.             GraphBuilder::new(builder_options, db, vfs, krate)
250.         };
251. 
252.         let focus_path: Vec<_> = {
253.             let path_string = options
254.                 .focus_on
255.                 .clone()
256.                 .unwrap_or_else(|| krate.display_name(db).unwrap().to_string());
257.             path_string.split("::").map(|c| c.to_owned()).collect()
258.         };
259. 
260.         trace!("Constructing graph ...");

