     Orphan,
     Trait,
     Type(TypeNode),
     TypeAlias,
     Value(ValueNode),
 }

 impl NodeKind {
     pub fn from(module_def: hir::ModuleDef, db: &RootDatabase) -> Option<Self> {
         match module_def {
             hir::ModuleDef::Module(module) => {
                 if module == module.crate_root(db) {
                     Some(NodeKind::Crate)
                 } else {
                     Some(NodeKind::Module)
                 }
             }
             hir::ModuleDef::Function(_) => Some(NodeKind::Function),
