 #[derive(Clone, PartialEq, Eq, Debug)]
 pub struct Options {
     pub focus_on: Option<String>,
     pub max_depth: Option<usize>,
     pub with_types: bool,
     pub with_tests: bool,
     pub with_orphans: bool,
     pub with_uses: bool,
