7.     path::{Path, PathBuf},
8. };
9. 
10. use log::trace;
11. use petgraph::graph::{EdgeIndex, NodeIndex};
12. use ra_ap_hir::{self as hir, Crate, ModuleSource};
13. use ra_ap_ide_db::RootDatabase;
14. use ra_ap_vfs::Vfs;
15. 
16. use crate::graph::{
17.     edge::{Edge, EdgeKind},
18.     node::{
19.         attr::{NodeAttrs, NodeCfgAttr, NodeTestAttr},
20.         visibility::NodeVisibility,
21.         Node, NodeKind,
22.     },
23.     orphans::add_orphan_nodes_to,
24.     util, Graph,
25. };
26. 
27. #[derive(Clone, PartialEq, Eq, Debug)]
28. pub struct Options {
29.     pub focus_on: Option<String>,
30.     pub max_depth: Option<usize>,
31.     pub with_types: bool,
32.     pub with_tests: bool,
33.     pub with_orphans: bool,
34.     pub with_uses: bool,
35.     pub with_externs: bool,
36. }
37. 
38. #[derive(Debug)]
39. pub struct Builder<'a> {
40.     options: Options,
41.     db: &'a RootDatabase,
42.     vfs: &'a Vfs,
43.     krate: hir::Crate,
44.     graph: Graph,
45.     nodes: HashMap<String, NodeIndex>,
46.     edges: HashMap<(NodeIndex, EdgeKind, NodeIndex), EdgeIndex>,
47. }
48. 
49. impl<'a> Builder<'a> {
50.     pub fn new(options: Options, db: &'a RootDatabase, vfs: &'a Vfs, krate: hir::Crate) -> Self {
51.         let graph = Graph::default();
52.         let nodes = HashMap::default();
53.         let edges = HashMap::default();
54. 
55.         Self {
56.             options,
57.             db,
58.             vfs,
59.             krate,
60.             graph,
61.             nodes,
62.             edges,
63.         }
64.     }
65. 
66.     pub fn build(mut self, krate: Crate) -> anyhow::Result<Graph> {
67.         trace!("Scanning project ...");
68. 
69.         self.process_crate(krate)?;
70. 
71.         Ok(self.graph)
72.     }
73. 
74.     fn process_crate(&mut self, krate: Crate) -> anyhow::Result<()> {
75.         let root_module = krate.root_module(self.db);
76.         let root_module_def = hir::ModuleDef::Module(root_module);
77. 
78.         self.process_owned_module_def(None, root_module_def)?;
79. 
80.         Ok(())
81.     }
82. 
83.     fn process_owned_module_def(
84.         &mut self,
85.         owner: Option<(hir::Module, NodeIndex)>,
86.         owned_module_def: hir::ModuleDef,
87.     ) -> anyhow::Result<Option<NodeIndex>> {
88.         if !self.options.with_types {
89.             // Check if target is a type (i.e. not a module).
90.             let is_module = matches!(owned_module_def, hir::ModuleDef::Module(_));
91. 
92.             // If it is a type we bail out:
93.             if !is_module {
94.                 return Ok(None);
95.             }
96.         }
97. 
98.         let (_owner_module, owner_idx) = match owner {
99.             Some((module, idx)) => (Some(module), Some(idx)),
100.             None => (None, None),
101.         };
102. 
103.         if !self.options.with_tests {
104.             if let hir::ModuleDef::Function(owned_function) = owned_module_def {
105.                 if util::is_test_function(owned_function, self.db) {
106.                     return Ok(None);
107.                 }
108.             }
109.         }
110. 
111.         let owned_idx = match self.add_node(owned_module_def) {
112.             Some(owned_idx) => owned_idx,
113.             None => return Ok(None),
114.         };
115. 
116.         if let Some(owner_idx) = owner_idx {
117.             let edge = Edge {
118.                 kind: EdgeKind::Owns,
119.             };
120.             self.add_edge(owner_idx, owned_idx, edge);
121.         }
122. 
123.         if let hir::ModuleDef::Module(owned_module) = owned_module_def {
124.             trace!(
125.                 "Scanning module {:?}",
126.                 util::path(owned_module_def, self.db)
127.             );
128. 
129.             let mut local_definitions: HashSet<hir::ModuleDef> = HashSet::new();
130. 
131.             for module_sub_def in owned_module.declarations(self.db) {
132.                 local_definitions.insert(module_sub_def);
133. 
134.                 self.process_owned_module_def(Some((owned_module, owned_idx)), module_sub_def)?;
135.             }
136. 
137.             if self.options.with_orphans && local_definitions.is_empty() {
138.                 add_orphan_nodes_to(&mut self.graph, owned_idx);
139.             }
140. 
141.             for (_name, scope_def) in owned_module.scope(self.db, None) {
142.                 if let hir::ScopeDef::ModuleDef(scope_module_def) = scope_def {
143.                     // Skip local child declarations:
144.                     if local_definitions.contains(&scope_module_def) {
145.                         continue;
146.                     }
147. 
148.                     self.process_used_module_def((owned_module, owned_idx), scope_module_def);
149.                 }
150.             }
151.         }
152. 
153.         if self.options.with_orphans {
154.             add_orphan_nodes_to(&mut self.graph, owned_idx);
155.         }
156. 
157.         Ok(Some(owned_idx))
158.     }
159. 
160.     fn process_used_module_def(
161.         &mut self,
162.         user: (hir::Module, NodeIndex),
163.         used_module_def: hir::ModuleDef,
164.     ) -> Option<NodeIndex> {
165.         if !self.options.with_uses {
166.             return None;
167.         }
168. 
169.         let (_user_module, user_idx) = user;
170. 
171.         let mut resolved_module_def = Some(used_module_def);
172. 
173.         if !self.options.with_types {
174.             // Check if target is a type (i.e. not a module).
175.             let is_module = matches!(used_module_def, hir::ModuleDef::Module(_));
176. 
177.             // If it is a type we need to resolve to its parent module instead:
178.             if !is_module {
179.                 let parent_module = used_module_def.module(self.db);
180.                 resolved_module_def = parent_module.map(hir::ModuleDef::Module);
181.             }
182.         }
183. 
184.         let module_def_krate = util::krate(used_module_def, self.db);
185. 
186.         // Check if target is from an extern crate.
187.         // If it is we need to resolve to its parent module instead:
188.         if module_def_krate != Some(self.krate) {
189.             resolved_module_def = if self.options.with_externs {
190.                 module_def_krate.map(|krate| hir::ModuleDef::Module(krate.root_module(self.db)))
191.             } else {
192.                 None
193.             };
194.         }
195. 
196.         // Depending on the options we might not want to add the target as is,
197.         // but resolve it to its module or crate, e.g., so we do that here:
198.         let resolved_module_def = match resolved_module_def {
199.             Some(resolved_module_def) => resolved_module_def,
200.             None => return None,
201.         };
202. 
203.         self.add_node(resolved_module_def).map(|used_idx| {
204.             let edge = Edge {
205.                 kind: EdgeKind::Uses,
206.             };
207.             self.add_edge(user_idx, used_idx, edge);
208.             used_idx
209.         })
210.     }
211. 
212.     fn add_node(&mut self, module_def: hir::ModuleDef) -> Option<NodeIndex> {
213.         let node_id = util::path(module_def, self.db);
214. 
215.         trace!("Adding module node: {:?}", node_id);
216. 
217.         // Check if we already added an equivalent node:
218.         match self.nodes.get(&node_id) {
219.             Some(node_idx) => {
220.                 // If we did indeed already process it, then retrieve its index:
221.                 Some(*node_idx)
222.             }
223.             None => {
224.                 // Otherwise try to add a node:
225.                 let node = match self.node_weight(module_def) {
226.                     Some(node) => node,
227.                     None => return None,
228.                 };
229. 
230.                 let node_idx = self.graph.add_node(node);
231.                 self.nodes.insert(node_id, node_idx);
232. 
