 use std::{
     collections::{HashMap, HashSet},
     path::{Path, PathBuf},
 };

 use log::trace;
 use petgraph::graph::{EdgeIndex, NodeIndex};
 use ra_ap_hir::{self as hir, Crate, ModuleSource};
